INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (1, 'mocktailwave', 'MocktailWave', '/img/mocktailwave.webp', 'mmi1', 'scolaire', '**MocktailWave** est une **carte interactive** pensée pour simplifier l’organisation de vos soirées dans les **bars du Doubs**.', 1, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (5, 'skillart', 'Projet SkillArt', '/img/skillart.webp', 'pro', 'perso-pro', 'Face à l’utilisation excessive de l’intelligence artificielle, **SkillArt** prend le contre-pied en proposant une **banque d’images** réservée aux **artistes** (graphistes, photographes, architectes) avec une **politique stricte** vis-à-vis de l’IA.', 3, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (4, 'redpanda-studio', 'RedPanda Studio', '/img/redpanda-studio.webp', 'mmi1', 'scolaire', '**Red Panda Studio** est un **studio de jeux vidéo indépendant** fondé sur l’**éco-conception** et engagé pour la protection du **panda roux**.', 4, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (3, 'matilda-presse', 'Matilda Presse', '/img/matilda-presse.webp', 'mmi1', 'scolaire', 'Un **site de presse** conçu pour sensibiliser à l’**effet Matilda**.', 5, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (7, 'taverne-etudiante', 'Taverne Étudiante', '/img/taverne-etudiante.webp', 'pro', 'perso-pro', '**La Taverne Étudiante** est une association qui avait pour mission initiale de faire **découvrir le JDR** (jeu de rôle) aux étudiants curieux de s’y essayer.', 6, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (6, 'e-commerce', 'E-Commerce', '/img/e-commerce.webp', 'pro', 'perso-pro', 'Un **site de vente en ligne** avec **livraison** pour une **épicerie parisienne**.', 7, 1);
INSERT INTO projects(id, slug, title, logo, context_id, grp, summary, position, published) VALUES (8, 'mini-jeux', 'Mini-Jeux', '/img/mini-jeux.svg', 'perso', 'perso-pro', 'Une série de **mini-jeux en JavaScript** (Snake, bataille navale, démineur) créés pour **perfectionner** ma maîtrise du langage.', 8, 1);
