INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (14, 1, 'contexte', 'Le sujet', 'Le sujet consistait à reprendre une idée d’application et à en réaliser le **budget**, la **communication**, le **volet légal** et le **développement**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (15, 1, 'contexte', 'Notre équipe', 'Nous formions une **équipe de 3** : un **développeur** (moi), un **graphiste** et un **responsable communication**.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (16, 1, 'contexte', 'Mon rôle', 'J’ai conçu une grande partie de la **maquette** avec le graphiste, et j’ai réalisé l’intégralité du développement **frontend** et **backend** de l’application.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (17, 1, 'processus', 'Maquette', 'Côté design, nous avons opté pour un look **rétro-wave** très marqué et original. Cette direction artistique était la plus parlante à nos yeux : c’est celle qui représentait le mieux **nos valeurs** et le **mouvement du sans-alcool**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (18, 1, 'processus', 'Développement', 'Le plus difficile a été de créer la **carte interactive**, avec la possibilité d’ajouter des bars à l’application en vérifiant via l’**API Google** qu’ils existent vraiment. Le second défi était le **GPS**, pour guider les utilisateurs de bar en bar et leur permettre de **rentrer en sécurité**.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (43, 3, 'contexte', 'Projet S1', 'Premier projet de fin de semestre de la formation MMI : créer un **site de presse** abordant l’**effet Matilda** à travers plusieurs supports.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (44, 3, 'contexte', 'Projet individuel', 'Ce projet était **individuel** : je me suis donc occupé à la fois du **design** et du **développement** du site.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (45, 3, 'processus', 'Cinématilda', 'Cette section présente différents **films** qui abordent le sujet, qu’il s’agisse d’œuvres de **sensibilisation** ou de **documentaires**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (46, 3, 'processus', 'Rosalind Franklin', 'J’ai choisi **Rosalind Franklin** comme figure principale de mon site, car son histoire illustre parfaitement la place faite aux **femmes dans la science** à son époque.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (47, 3, 'processus', 'Supports', 'Le site propose plusieurs pages pour sensibiliser à travers une **expérience immersive** : d’abord le **cinéma**, ensuite l’histoire de Rosalind et la découverte de l’**ADN en double hélice**, puis une **fresque** des femmes scientifiques oubliées, et enfin l’**extrait d’un livre** consacré à cette découverte.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (38, 4, 'contexte', 'SAÉ 106', 'Le but de cette SAÉ était de créer une **organisation** et de prévoir comment elle allait générer des revenus (**budget**, **plan de communication**, **ciblage**, etc.). Le sujet imposait aussi une **dimension écologique**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (39, 4, 'contexte', 'Notre idée', 'Nous sommes partis sur l’idée d’un **studio de jeux vidéo** engagé pour les **animaux en voie de disparition**.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (40, 4, 'processus', 'Le panda roux', 'Nous avons choisi de consacrer notre engagement au **panda roux**, un animal **attachant** et facilement **reconnaissable**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (41, 4, 'processus', 'Le concept', 'Red Panda Studio reverse **15 % de son chiffre d’affaires** à des associations de sauvegarde du panda roux. Notre éco-responsabilité repose ainsi sur deux piliers :
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (42, 4, 'processus', 'Ciblage', 'Nous visons les **jeunes adultes** et les **étudiants**, joueurs occasionnels ou réguliers, **socialement engagés** et sensibles à l’**environnement**.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (30, 5, 'contexte', 'Notre équipe', 'Exclusivement composée **d’étudiants**, l’équipe de SkillArt réunit un large panel de compétences (BUT Réseaux et Télécommunications, BUT Informatique, BUT Métiers du Multimédia et de l’Internet).', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (31, 5, 'contexte', 'Mon rôle', 'Au sein de cette équipe, j’occupe plusieurs rôles : **chef de projet**, **responsable communication** et **designer d’interface**.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (32, 5, 'contexte', 'Nos valeurs', 'L’**art** et la **culture** sont pour nous des valeurs essentielles, qui ne devraient pas disparaître à cause de l’intelligence artificielle.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (33, 5, 'contexte', 'Notre but', 'Le but premier de SkillArt est de provoquer une **prise de conscience** sur l’impact de l’IA sur l’art et la culture.', 4);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (34, 5, 'processus', 'Réflexions', 'Nos réflexions ont porté sur plusieurs sujets : le **public visé**, le **nom**, les **fonctionnalités clés** et les **pistes graphiques**.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (35, 5, 'processus', 'Obstacles', 'Le plus grand défi de ce projet : réussir à **identifier les publications générées par IA** pour les supprimer.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (36, 5, 'processus', 'Résultats', 'Pour le nom, deux idées se sont démarquées : **Skeetch** et **SkillArt**. Nous avons finalement retenu **SkillArt**, qui se distinguait davantage de l’existant. Côté public, nous ciblons avant tout les **artistes**, et nous avons pensé nos fonctionnalités en conséquence.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (37, 5, 'processus', 'Solutions', 'Pour repérer les publications générées par IA, nous combinons deux solutions : d’abord un **algorithme** qui recherche dans l’image toute **signature d’IA générative** connue, visible ou invisible ; ensuite un **système de vote** qui fait évoluer le **score de confiance** de chaque utilisateur.', 4);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (23, 6, 'contexte', 'Pourquoi ?', 'Une entreprise que j’avais démarchée m’a confié la création de son **site web** pour **vendre ses produits** en ligne.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (24, 6, 'contexte', 'La mission', '- plus de **1 000 produits** à référencer via une **API de gestion des stocks et des prix** ;
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (25, 6, 'contexte', 'Le défi', 'Je n’avais encore jamais réalisé de site pour des **professionnels**, et la mission était exigeante : j’avais beaucoup de **nouvelles compétences** à acquérir pour y parvenir.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (26, 6, 'processus', 'Phase de conception', 'Pour les convaincre de travailler avec moi, j’ai d’abord créé une **première version** avec un **frontend** fidèle à leur image.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (27, 6, 'processus', 'Négociation', 'Nous avons ensuite défini ensemble le **prix** et le **cahier des charges**.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (28, 6, 'processus', 'Création', 'J’ai ensuite travaillé pendant près de **6 mois** avec un membre de leur équipe, qui me transmettait les **améliorations** et les **modifications** à apporter.', 3);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (29, 6, 'processus', 'Fin du projet', 'Le projet a été **livré avec toutes les fonctionnalités** prévues, mais le site n’a malheureusement jamais été mis en ligne : l’entreprise n’est pas allée au bout de la démarche.', 4);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (19, 7, 'contexte', 'La création', 'L’idée est née avec un groupe d’amis fans de JDR : créer un **club** au sein du département pour organiser des **sessions de jeu**. Le projet a été vivement encouragé par le **chef de département**, qui nous a permis de fonder l’association.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (20, 7, 'contexte', 'L’équipe', 'L’association compte **5 membres actifs** et accueille régulièrement des invités : **Maël Brungard**, Alexandre Guillet, Théo Philbert, Estelle Coulon et Merlin Henry.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (21, 7, 'processus', 'Campagne Port Mouton', 'Pour faire découvrir le JDR, nous avons écrit notre **propre campagne**, inspirée des règles de **Donjons et Dragons**. Nous avons créé tout un **univers de A à Z** dans un PDF de 30 pages : une région, des îles, des personnages, une politique, etc.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (22, 7, 'processus', 'Podcast Donjons et Saucissons', 'Pour faire connaître l’association et la campagne de Port Mouton, nous avons créé un **podcast** dans lequel nous jouons cette campagne. Nous le diffusons **en direct sur Twitch**, ainsi qu’en **version montée** sur YouTube, Spotify, Instagram et TikTok.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (9, 8, 'contexte', 'JavaScript', 'Il s’agit d’une série de **défis** que je me suis lancés pour **approfondir** mes compétences et **perfectionner** ma maîtrise du JavaScript.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (10, 8, 'contexte', 'GitHub', 'Les rendre **publics sur GitHub** m’a permis d’étoffer mes **dépôts**, d’avoir un **profil complet** et de partager mon code et ma démarche.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (11, 8, 'processus', 'Snake', 'Le premier jeu est un **Snake**, que j’ai créé pour pouvoir modifier librement les **réglages** et la **difficulté**. L’objectif était de **ne pas utiliser l’IA**, sauf pour le frontend minimaliste.', 1);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (12, 8, 'processus', 'Bataille navale', 'Dans le même esprit, j’ai créé une **bataille navale** avec un **placement aléatoire** des bateaux à retrouver.', 2);
INSERT INTO sections(id, project_id, tab, title, body, position) VALUES (13, 8, 'processus', 'Démineur', 'Enfin, par **curiosité**, j’ai cherché à **comprendre** le fonctionnement du démineur pour pouvoir le reproduire à mon tour.', 3);
